def parse_price(s: str) -> float:
    """Parse a US-formatted price string like '$1,200.50' into a float."""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    # Remove leading/trailing whitespace
    s = s.strip()
    # Remove leading $ if present
    if s.startswith('$'):
        s = s[1:]
    # Remove commas
    s = s.replace(',', '')
    # If empty after cleanup, treat as 0
    if s == '':
        return 0.0
    # If no decimal point, assume integer dollars
    if '.' not in s:
        s += '.0'
    try:
        return float(s)
    except ValueError:
        raise ValueError(f"Cannot parse price from '{s}'")

def merge_intervals(iv: list) -> list:
    """Merge overlapping [start, end] intervals; return them sorted by start. Touching intervals merge."""
    if not iv:
        return []
    # sort by start
    intervals = sorted(iv, key=lambda x: x[0])
    merged = [intervals[0]]
    for cur in intervals[1:]:
        last = merged[-1]
        # if current starts before or at last.end + 1 (touching), merge
        if cur[0] <= last[1] + 1:
            # update end to max
            last[1] = max(last[1], cur[1])
        else:
            merged.append(cur)
    return merged

def word_count(text: str) -> dict:
    """Count lowercase words (split on whitespace, strip .,!? from both ends)."""
    from collections import Counter
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    words = text.split()
    cleaned = []
    for w in words:
        # strip punctuation from both ends
        stripped = w.strip(".,!?")
        if stripped:
            cleaned.append(stripped.lower())
    return dict(Counter(cleaned))

def fizzbuzz(n: int) -> list:
    """Return the FizzBuzz strings for 1..n ('Fizz' for multiples of 3, 'Buzz' for 5, 'FizzBuzz' for both)."""
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append('FizzBuzz')
        elif i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        else:
            result.append(str(i))
    return result

def sort_versions(vs: list) -> list:
    """Sort semantic version strings ascending by (major, minor, patch)."""
    def parse(v: str):
        major, minor, patch = (int(x) for x in v.split('.'))
        return (major, minor, patch)
    return [f"{m}.{mi}.{p}" for m, mi, p in sorted((parse(v), v) for v in vs)][0:len(vs)]

def run_length_encode(s: str) -> str:
    """Compress runs of repeated characters as <char><count>. Single characters keep count 1."""
    if not s:
        return ""
    result = []
    current_char = s[0]
    count = 1
    for ch in s[1:]:
        if ch == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = ch
            count = 1
    result.append(f"{current_char}{count}")
    return "".join(result)

def second_largest(nums: list) -> int:
    """Return the second largest distinct value; raise ValueError if there is none."""
    # Convert to set to remove duplicates and sort
    unique = set(nums)
    if len(unique) < 2:
        raise ValueError("Not enough distinct values")
    # Get largest and second largest
    largest = max(unique)
    unique.remove(largest)
    return max(unique)

def normalize_phone(s: str) -> str:
    # Extract digits
    digits = ''.join(ch for ch in s if ch.isdigit())
    if len(digits) != 10:
        raise ValueError("Phone number must have 10 digits")
    area, prefix, line = digits[:3], digits[3:6], digits[6:]
    # Determine output format based on presence of '(' in original string
    if '(' in s:
        # plain dashes
        return f"{area}-{prefix}-{line}"
    else:
        return f"({area}) {prefix}-{line}"

def parse_price(s: str) -> float:
    """Parse a US-formatted price string like '$1,200.50' into a float.

    Handles leading/trailing whitespace, optional leading '$', and commas as thousand separators.
    """
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    # strip whitespace
    s = s.strip()
    if not s:
        raise ValueError("Empty string")
    # remove leading dollar sign if present
    if s[0] == '$':
        s = s[1:]
    # remove commas
    s = s.replace(',', '')
    # if string is just a number or has decimal
    try:
        return float(s)
    except ValueError as e:
        raise ValueError(f"Invalid price format: {s}") from e
